import { cacheLife, cacheTag } from 'next/cache'

// Requires cacheComponents: true in next.config.ts
export async function getPosts() {
  'use cache'
  cacheLife('hours')
  cacheTag('posts')

  const response = await fetch('https://api.vercel.app/blog')
  if (!response.ok) throw new Error('Posts request failed')
  return response.json()
}

import { Suspense } from 'react'

type Forecast = { current: { temperature_2m: number } }

async function Weather() {
  const response = await fetch(
    'https://api.open-meteo.com/v1/forecast?latitude=52.52&longitude=13.41&current=temperature_2m',
    { cache: 'no-store' },
  )
  const data: Forecast = await response.json()

  return <p>Berlin: {data.current.temperature_2m} °C</p>
}

export default function Page() {
  return (
    <main>
      <h1>Trailhead</h1>
      <Suspense fallback={<p>Loading the current temperature</p>}>
        <Weather />
      </Suspense>
    </main>
  )
}

'use server'

import { updateTag } from 'next/cache'
import { redirect } from 'next/navigation'
import { db } from '@/lib/db'

export async function publishPost(id: string) {
  await db.post.update({ where: { id }, data: { published: true } })

  // Expire the tag now so the author sees the change immediately
  updateTag('posts')
  redirect(`/blog/${id}`)
}

